pattern.example:
from functools import wraps

def with_status(message: str, icon: str = "🔄"):
    """Decorator for wrapping functions with status emission"""
    def decorator(func):
        @wraps(func)
        async def wrapper(*args, **kwargs):
            emit_status(message, icon)
            return await func(*args, **kwargs)
        return wrapper
    return decorator
